/**
 * The API client: openapi-fetch, typed from FastAPI's schema (decision 0010).
 * `schema.d.ts` is generated by `npm run api`; never edit it by hand.
 */
import createClient, { type Client } from "openapi-fetch";
import * as v from "valibot";
import type { components, paths } from "./schema";

export type Api = Client<paths>;
export type Schemas = components["schemas"];

/** Same origin as the pages, so the device cookie goes with every call. */
export function makeApi(fetch?: (request: Request) => Promise<Response>): Api {
  return createClient<paths>(fetch === undefined ? {} : { fetch });
}

/** For each status a call expects, what its body must look like. */
type Expected = { [status: number]: v.GenericSchema };

/**
 * A reply, once checked: one of the expected statuses with a body that
 * passed its schema, or one of three things every call can meet.
 */
export type Checked<E extends Expected> =
  | {
      [S in keyof E & number]: { status: S; body: v.InferOutput<E[S]> };
    }[keyof E & number]
  // The database, or a proxy in front of the app, cannot answer just now:
  // worth trying again soon.
  | { status: "unavailable" }
  // No answer at all.
  | { status: "offline" }
  // A status, or a body, this build does not understand.
  | { status: "unexpected"; code: number };

/** What openapi-fetch resolves to, whatever the call. */
type Sent = { data?: unknown; error?: unknown; response: Response };

const UNAVAILABLE = new Set([502, 503, 504]);

/**
 * Check a call's reply against what it expects. The generated types promise
 * a body for each status, but nothing checks it: a proxy's error page
 * arrives as text, and a newer server may send what this build does not
 * know. So nothing reaches a page unchecked.
 */
export async function check<E extends Expected>(
  call: Promise<Sent>,
  expected: E,
): Promise<Checked<E>> {
  let sent: Sent;
  try {
    sent = await call;
  } catch {
    // Offline, or a success whose body is not JSON, which is no answer
    // this build can use either.
    return { status: "offline" };
  }
  const code = sent.response.status;
  const schema = expected[code];
  if (schema !== undefined) {
    const parsed = v.safeParse(schema, sent.data ?? sent.error);
    if (parsed.success) {
      return { status: code, body: parsed.output } as Checked<E>;
    }
  } else if (UNAVAILABLE.has(code)) {
    return { status: "unavailable" };
  }
  return { status: "unexpected", code };
}
